<form method="post" action="/control-center/security" class="card rounded-2xl border border-stone-200 bg-white p-6 shadow-sm max-w-xl space-y-5"><h2 class="font-display [overflow-wrap:anywhere] text-3xl">Change your password</h2><p class="text-sm text-stone-500">All your existing sessions will be revoked after a password change.</p><?= csrf() ?><label class="block text-sm font-medium">Current password<input class="w-full rounded-lg border border-stone-300 bg-white p-3 text-sm text-ink [&[type=checkbox]]:w-auto [&[type=radio]]:w-auto" type="password" name="current_password" autocomplete="current-password" required></label><label class="block text-sm font-medium">New password<input class="w-full rounded-lg border border-stone-300 bg-white p-3 text-sm text-ink [&[type=checkbox]]:w-auto [&[type=radio]]:w-auto" type="password" name="password" autocomplete="new-password" minlength="12" maxlength="200" required></label><button class="btn-dark inline-flex items-center justify-center rounded-full px-6 py-3 text-sm font-semibold text-white transition disabled:opacity-40 bg-ink hover:bg-stone-700">Change password</button></form>
